-- ============================================================================================
-- CVM_CONTACT_T2_20261101 — ускорение процедуры dbo.CVM_CONTACT (шаг CVM_CONTACT задания «MCI Regular update», витрина
--   I_CVM_CONTACT). Бэклог ночного задания Т2, согласован Еленой 31.10.2026 («весь список правок без смены цифр»).
-- Выполняется заданием CVM_API_nightly из обменника. Новых таблиц, процедур, шагов и заданий не создаёт.
--
-- Зачем: шаг идёт 1:48–1:50 (30.10, 31.10, 01.11) и за прогон читает всю историю чеков (1,77 млрд заголовков) пять раз,
--   окна 6–56 недель — ещё шесть раз, строки чеков 6 недель — дважды. Ожидаемо: шаг короче на 30–60 мин.
-- Что меняется в процедуре — вставками в живой текст (куски правки ниже, остальной текст — как есть; полный новый текст и разница —
--   output/Аудит_ночного_задания_2026-10-31/Т2_CVM_CONTACT_новый_текст.sql и Т2_CVM_CONTACT_разница.diff):
--   CC-1  #for_cg (вся история × I_CONTACT_PRICE_SEGMENT × I_CONTACT) не строится: LTV = round(сумма чеков за всю историю
--         / 100) * 100 — та же сумма уже есть в #first_purch;
--   CC-2  вся история читается один раз (#hist): из неё #first_purch, «Новые» и канал #m (было три прохода);
--   CC-4  окна 56/52/6 недель и 6 недель год назад — один проход (#wk, без чеков клиента 0): «Случайные», «Отток»,
--         «Активные» (было шесть);
--   CC-3  любимый магазин: пары «магазин × день» за 26 недель, историю — только клиентам, у кого в 26 неделях меньше 8 пар;
--         номера пар — один раз (было: вся история, дважды);
--   CC-5  любимые товары и категории: строки чеков 6 недель — один раз и только по клиентам с выбором, категория —
--         полусоединением по каждому уровню (было: два прохода и соединение через OR);
--   CC-6  вставка в I_CVM_CONTACT WITH (TABLOCK); CC-7 колоночные индексы на временных таблицах на миллионы строк;
--   CC-8  OPTION (RECOMPILE) на чтениях окон.
-- Как применяется (всё — в этом скрипте):
--   1. Проверки: текст процедуры — тот, по которому собрана правка (SHA2_256), ANSI_NULLS и QUOTED_IDENTIFIER у неё ON;
--      старт 17:00–22:00 по серверу; не идут «MCI Regular update» и загрузка MCI; I_CVM_CONTACT посчитана на последних
--      чеках (REFERENCE_DATE = max(DATA)).
--   2. Новая версия процедуры прогоняется целиком в сессии скрипта; результат — во временную #new, I_CVM_CONTACT не
--      трогается (в тексте прогона I_CVM_CONTACT заменена на #new, скрипт проверяет, что других упоминаний нет).
--   3. #new сверяется с I_CVM_CONTACT по каждой из 60 колонок (ключ — компания, организация, клиент).
--      Обязаны совпасть: число строк и ключи, все колонки, кроме перечисленных ниже.
--      Не входят в условие (их источники меняются после шага в течение дня или их пишет следующий шаг — считаются
--      как прежде, правка их не касается): PRICE_INDEX, LOYALTY_INDEX (I_CONTACT_PRICE_SEGMENT пересчитывает шаг
--      после CVM_CONTACT), PP_USE, CVM_PARTICIPANT, LOYALTY_PROMO_PARTICIPANT (I_PROMO меняется днём),
--      AFFINITIVE_SCORE (пишет шаг AFFINITIVE_MODEL).
--      «Ничьи» в исходной процедуре: SEGMENT зависит от порядка недель с покупками в двух организациях в одну неделю
--      (LAG без второго ключа сортировки), LOVE_STORE и ID_DARKSTORE — от порядка магазинов в один день (ROW_NUMBER по
--      дате) — у таких клиентов результат меняется от прогона к прогону и в прежней версии. Их расхождения считаются
--      отдельно и в условие не входят; у остальных клиентов SEGMENT, LOVE_STORE, ID_DARKSTORE обязаны совпасть.
--   4. Только если всё совпало и прогон занял не больше @max_min минут — прежний текст в dbo.I_DISCOUNT_PROC_BACKUP
--      (PROC_NAME = 'CVM_CONTACT') и ALTER PROCEDURE одной транзакцией со сверкой хэша нового текста; иначе процедура
--      не меняется.
--   Итог (JSON: сверка по колонкам, «ничьи», сегменты до/после, время блоков) — строкой в dbo.I_DISCOUNT_PROC_BACKUP,
--   PROC_NAME = 'CVM_CONTACT T2 сверка'. Есть такая строка — скрипт тяжёлую сверку повторно не запускает.
-- Сообщения раннеру — латиницей (журнал CVM_API_JOB_LOG теряет кириллицу).
-- Откат после применения: CVM_CONTACT_T2_ROLLBACK_20261101.sql (возвращает текст из I_DISCOUNT_PROC_BACKUP).
-- Проверка: SELECT DEFINITION FROM dbo.I_DISCOUNT_PROC_BACKUP (nolock) WHERE PROC_NAME = N'CVM_CONTACT T2 сверка';
-- ============================================================================================

USE mci_model
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_WARNINGS ON;
SET ANSI_PADDING ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
GO

DECLARE @sha_old  varbinary(32) = 0xF1BEAC3B625815FCEAC63A6FDF42FD0937A03CD3762DE1768824B949290EDBAF      -- текст CVM_CONTACT в базе с 11.10.2026 (снят 01.11.2026)
      , @sha_new  varbinary(32) = 0xDDF8ACB33D464C74DDB9D6F77880DF79018327FD9B7BC7E4368323FF7DC66579      -- текст после правок Т2
      , @max_min  int = 100                            -- ALTER, только если прогон не дольше (шаг сейчас 108–110 мин)
      , @rep_name sysname = N'CVM_CONTACT T2 сверка'
      , @hdr_c nvarchar(60) = N'CREATE PROCEDURE  [dbo].[CVM_CONTACT]'
      , @hdr_a nvarchar(60) = N'ALTER PROCEDURE  [dbo].[CVM_CONTACT]'
      , @crlf nchar(2) = NCHAR(13) + NCHAR(10)
      , @def nvarchar(max), @new_def nvarchar(max), @body nvarchar(max), @alter nvarchar(max), @o nvarchar(max)
      , @n nvarchar(max), @k int, @kmax int, @pos int, @len int, @msg nvarchar(2048)
      , @act_date date, @ref_date date, @run_at datetime2(0) = SYSDATETIME()
      , @dup_old bigint, @dup_new bigint, @dup_icontact bigint, @minutes int, @why nvarchar(max) = N''
      , @seg_json nvarchar(max), @log_json nvarchar(max), @cmp_json nvarchar(max), @report nvarchar(max), @step nvarchar(100);

-- ============================== 0. ПРОВЕРКИ ==============================
-- Раннер вызывает sqlcmd с -b: RAISERROR 16 обрывает скрипт, он остаётся в обменнике и повторяется через 10 минут.
-- Поэтому «Wait» — там, где надо подождать; «уже сделано» — не ошибка.
SET @def = OBJECT_DEFINITION(OBJECT_ID(N'dbo.CVM_CONTACT'));
IF @def IS NULL
BEGIN
    RAISERROR(N'STOP: dbo.CVM_CONTACT not found or no rights to its text — nothing changed.', 16, 1);
    RETURN;
END
IF HASHBYTES('SHA2_256', REPLACE(@def COLLATE Latin1_General_BIN2, @hdr_a, @hdr_c)) = @sha_new
BEGIN
    PRINT N'T2: CVM_CONTACT already in T2 version — nothing to do.';
    RETURN;
END
IF HASHBYTES('SHA2_256', REPLACE(@def COLLATE Latin1_General_BIN2, @hdr_a, @hdr_c)) <> @sha_old
BEGIN
    RAISERROR(N'STOP: CVM_CONTACT text changed after 11.10.2026 (not the one T2 was built on) — nothing changed.', 16, 1);
    RETURN;
END
-- ALTER из этого скрипта идёт с ANSI_NULLS ON и QUOTED_IDENTIFIER ON (SET выше); у процедуры они должны быть такими же
IF ISNULL(OBJECTPROPERTY(OBJECT_ID(N'dbo.CVM_CONTACT'), 'ExecIsAnsiNullsOn'), 0) <> 1
   OR ISNULL(OBJECTPROPERTY(OBJECT_ID(N'dbo.CVM_CONTACT'), 'ExecIsQuotedIdentOn'), 0) <> 1
BEGIN
    RAISERROR(N'STOP: CVM_CONTACT has ANSI_NULLS or QUOTED_IDENTIFIER OFF; ALTER would switch them ON — nothing changed.', 16, 1);
    RETURN;
END
IF EXISTS (SELECT 1 FROM dbo.I_DISCOUNT_PROC_BACKUP (nolock) WHERE PROC_NAME = @rep_name)
BEGIN
    PRINT N'T2: check already ran (I_DISCOUNT_PROC_BACKUP, PROC_NAME = ''CVM_CONTACT T2 сверка'') — not repeating it.';
    RETURN;
END
-- конец окна 22:00: с тайм-аутом sqlcmd 3 ч прогон кончится до 01:00, когда стартует «MCI Reload every day»
IF CAST(GETDATE() AS time) NOT BETWEEN '17:00' AND '22:00'
BEGIN
    RAISERROR(N'Wait: T2 check takes 1-1.5 h, runs only 17:00-22:00 server time; exchange will retry in 10 min.', 16, 1);
    RETURN;
END
IF EXISTS (SELECT 1
           FROM msdb.dbo.sysjobactivity AS a (nolock)
                JOIN msdb.dbo.sysjobs AS j (nolock) ON j.job_id = a.job_id
           WHERE j.name IN (N'MCI Regular update', N'MCI Reload every day', N'MCI Reload one time', N'MCI Reload',
                            N'CVM REBUILD ONCE')
             AND a.session_id = (SELECT max(s.session_id) FROM msdb.dbo.syssessions AS s (nolock))
             AND a.start_execution_date IS NOT NULL AND a.stop_execution_date IS NULL)
BEGIN
    RAISERROR(N'Job running: MCI Regular update or MCI load is running; exchange will retry in 10 min.', 16, 1);
    RETURN;
END
-- витрина той же структуры, что пишет процедура (вставка без списка колонок)
IF (SELECT COUNT(*) FROM sys.columns (nolock) WHERE object_id = OBJECT_ID(N'dbo.I_CVM_CONTACT')) <> 60
   OR ISNULL((SELECT TOP (1) name FROM sys.columns (nolock) WHERE object_id = OBJECT_ID(N'dbo.I_CVM_CONTACT')
              ORDER BY column_id DESC), N'') <> N'PUSH_CLICK_COUNT'
BEGIN
    RAISERROR(N'STOP: I_CVM_CONTACT does not have 60 columns ending with PUSH_CLICK_COUNT — nothing changed.', 16, 1);
    RETURN;
END
-- сверка честная, только если I_CVM_CONTACT посчитана на тех же чеках, что видит прогон
SELECT @act_date = max(DATA) FROM dbo.I_CHECKHEADER (nolock) WHERE ID_COMPANY = 1;
SELECT TOP (1) @ref_date = REFERENCE_DATE FROM dbo.I_CVM_CONTACT (nolock);
IF @ref_date IS NULL OR @act_date IS NULL OR @ref_date <> @act_date
BEGIN
    SET @msg = CONCAT(N'Wait: I_CVM_CONTACT REFERENCE_DATE ', @ref_date, N' <> last check date ', @act_date,
                      N' — step CVM_CONTACT has not run on current checks; exchange will retry in 10 min.');
    RAISERROR(N'%s', 16, 1, @msg);
    RETURN;
END

-- ============================== 1. НОВЫЙ ТЕКСТ — ВСТАВКАМИ В ЖИВОЙ ТЕКСТ ==============================
-- Каждая правка: прежний кусок (с 5 строками окружения) → новый. Куски — UTF-16 в шестнадцатеричном виде, чтобы
-- переводы строк, табуляции и пробелы в конце строк дошли до сервера байт в байт. Прежний кусок обязан встретиться
-- в тексте ровно один раз; итог сверяется по хэшу с новым текстом, собранным и проверенным заранее.
DECLARE @h TABLE (K int NOT NULL PRIMARY KEY, O varbinary(max) NOT NULL, N varbinary(max) NOT NULL);
DECLARE @vo varbinary(max), @vn varbinary(max);
-- правка 1: строки прежнего текста 25,29 → нового 25,56
SET @vo = 0x;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (1, @vo, @vn);
-- правка 2: строки прежнего текста 87,55 → нового 114,73
SET @vo = 0x;
SET @vo = @vo + ;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
SET @vn = @vn + ;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (2, @vo, @vn);
-- правка 3: строки прежнего текста 160,28 → нового 205,30
SET @vo = 0x;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (3, @vo, @vn);
-- правка 4: строки прежнего текста 208,41 → нового 255,43
SET @vo = 0x;
SET @vo = @vo + ;
SET @vo = @vo + 0x09002C00200061002E00490044005F004F005200470041004E0049005A004100540049004F004E000D000A000900090009002C00200061002E00490044005F0043004F004D00500041004E00590020000D000A00;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (4, @vo, @vn);
-- правка 5: строки прежнего текста 256,37 → нового 305,42
SET @vo = 0x;
SET @vo = @vo + ;
SET @vo = @vo + 0x2C00200061002E00490044005F0043004F004D00500041004E0059000D000A0009002C00200062002E00490044005F0043004F004E0054004100430054000D000A000D000A00;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (5, @vo, @vn);
-- правка 6: строки прежнего текста 321,22 → нового 375,25
SET @vo = 0x;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (6, @vo, @vn);
-- правка 7: строки прежнего текста 378,50 → нового 435,17
SET @vo = 0x;
SET @vo = @vo + ;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (7, @vo, @vn);
-- правка 8: строки прежнего текста 430,29 → нового 454,89
SET @vo = 0x;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
SET @vn = @vn + ;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (8, @vo, @vn);
-- правка 9: строки прежнего текста 509,142 → нового 593,178
SET @vo = 0x;
SET @vo = @vo + ;
SET @vo = @vo + ;
SET @vo = @vo + ;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
SET @vn = @vn + ;
SET @vn = @vn + ;
SET @vn = @vn + ;
SET @vn = @vn + ;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (9, @vo, @vn);
-- правка 10: строки прежнего текста 726,11 → нового 846,12
SET @vo = 0x;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (10, @vo, @vn);
-- правка 11: строки прежнего текста 776,14 → нового 897,15
SET @vo = 0x;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (11, @vo, @vn);
-- правка 12: строки прежнего текста 828,11 → нового 950,11
SET @vo = 0x;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (12, @vo, @vn);
-- правка 13: строки прежнего текста 858,14 → нового 980,10
SET @vo = 0x;
SET @vo = @vo + ;
SET @vn = 0x;
SET @vn = @vn + ;
INSERT @h (K, O, N) VALUES (13, @vo, @vn);

SET @new_def = @def;
SELECT @k = 1, @kmax = MAX(K) FROM @h;
WHILE @k <= @kmax
BEGIN
    SELECT @o = CAST(O AS nvarchar(max)), @n = CAST(N AS nvarchar(max)) FROM @h WHERE K = @k;
    SET @len = DATALENGTH(@o) / 2;
    SET @pos = CHARINDEX(LEFT(@o, 300) COLLATE Latin1_General_BIN2, @new_def COLLATE Latin1_General_BIN2);
    IF @pos = 0
       OR CHARINDEX(LEFT(@o, 300) COLLATE Latin1_General_BIN2, @new_def COLLATE Latin1_General_BIN2, @pos + 1) > 0
       OR HASHBYTES('SHA2_256', SUBSTRING(@new_def, @pos, @len)) <> HASHBYTES('SHA2_256', @o)
    BEGIN
        SET @msg = CONCAT(N'STOP: T2 edit ', @k, N' — old fragment not found exactly once; nothing changed.');
        RAISERROR(N'%s', 16, 1, @msg);
        RETURN;
    END
    SET @new_def = STUFF(@new_def, @pos, @len, @n);
    SET @k += 1;
END
IF HASHBYTES('SHA2_256', @new_def) <> @sha_new
BEGIN
    RAISERROR(N'STOP: T2 text after edits does not match the prepared one — nothing changed.', 16, 1);
    RETURN;
END

-- ============================== 2. ПРОГОН НОВОЙ ВЕРСИИ В СЕССИИ — В #new ==============================
-- текст прогона: тело процедуры (после «as»), I_CVM_CONTACT → #new, отметки времени перед блоками, в конце — «ничьи»
SET @pos = CHARINDEX(@crlf + N'as' + @crlf, @new_def COLLATE Latin1_General_BIN2);
IF @pos = 0 OR @pos > 60
BEGIN
    RAISERROR(N'STOP: T2 procedure header not recognised — nothing changed.', 16, 1);
    RETURN;
END
SET @body = SUBSTRING(@new_def, @pos + 6, DATALENGTH(@new_def) / 2);
SET @body = REPLACE(@body COLLATE Latin1_General_BIN2, N'I_CVM_CONTACT', N'#new');
IF CHARINDEX(N'I_CVM_CONTACT' COLLATE Latin1_General_BIN2, UPPER(@body) COLLATE Latin1_General_BIN2) > 0   -- без учёта регистра
   OR CHARINDEX(N'INSERT INTO #new WITH (TABLOCK)' COLLATE Latin1_General_BIN2, @body COLLATE Latin1_General_BIN2) = 0
BEGIN
    RAISERROR(N'STOP: T2 test text still writes I_CVM_CONTACT or has no insert into #new — nothing changed.', 16, 1);
    RETURN;
END

DECLARE @anch TABLE (K int IDENTITY(1,1) PRIMARY KEY, A nvarchar(200) NOT NULL, B nvarchar(40) NOT NULL);
INSERT @anch (A, B) VALUES
      (N'drop table if exists #hist;', N'hist'),
      (N'---- 0 -fraud', N'segment_0'),
      (N'drop table if exists #wk;', N'wk'),
      (N'-- 4- RANDOM', N'random'),
      (N'-- 5- CHURN', N'churn'),
      (N'-- 2- ACTIVE, 3 - ACTIVE LFL', N'active'),
      (N'--sleeping', N'sleeping'),
      (N'---channel select', N'channel'),
      (N'--basic index', N'all_p'),
      (N'--darkstore', N'main_shop'),
      (N'drop table if exists #fp_t2', N'fav'),
      (N'drop table if exists #camp;', N'camp'),
      (N'drop table if exists #rule_use;', N'rule_use'),
      (N'drop table if exists #push;', N'push'),
      (N'--all cvm', N'insert');
SELECT @k = 1, @kmax = MAX(K) FROM @anch;
WHILE @k <= @kmax
BEGIN
    SELECT @o = A, @n = B FROM @anch WHERE K = @k;
    SET @pos = CHARINDEX(@o COLLATE Latin1_General_BIN2, @body COLLATE Latin1_General_BIN2);
    IF @pos = 0 OR CHARINDEX(@o COLLATE Latin1_General_BIN2, @body COLLATE Latin1_General_BIN2, @pos + 1) > 0
    BEGIN
        SET @msg = CONCAT(N'STOP: T2 timing anchor ', @n, N' not found exactly once — nothing changed.');
        RAISERROR(N'%s', 16, 1, @msg);
        RETURN;
    END
    SET @body = STUFF(@body, @pos, 0, N'insert into #t2_log (BLOCK, AT) values (N''' + @n + N''', sysdatetime());' + @crlf);
    SET @k += 1;
END
SET @body = @body + @crlf
    + N'insert into #t2_log (BLOCK, AT) values (N''end'', sysdatetime());' + @crlf
    -- «ничьи» недель: у клиента в одну неделю покупки в двух организациях — LAG по неделе без второго ключа
    + N'insert into #tie_w (ID_CONTACT) select distinct ID_CONTACT from (select ID_CONTACT from #wk'
    + N' where N56 > 0 and ID_CONTACT != 0 group by ID_CONTACT, WEEKNUMBER having count(*) > 1) q;' + @crlf
    -- «ничьи» магазинов: в один из 8 последних дней с покупками — два магазина и больше (ROW_NUMBER по дате)
    + N'insert into #tie_s (ID_CONTACT) select distinct ID_CONTACT from (select ID_CONTACT, N = count(*)'
    + N', DR = dense_rank() over (partition by ID_CONTACT order by DATA desc) from #sd group by ID_CONTACT, DATA) q'
    + N' where N > 1 and DR <= 8;' + @crlf;

DROP TABLE IF EXISTS #new, #tie_w, #tie_s, #t2_log, #cmp;
SELECT TOP (0) * INTO #new FROM dbo.I_CVM_CONTACT (nolock);
CREATE CLUSTERED COLUMNSTORE INDEX cci_new ON #new;   -- 15 млн строк × 60 колонок: колоночная, не куча 7,5 ГБ в tempdb
CREATE TABLE #tie_w (ID_CONTACT int NOT NULL);
CREATE TABLE #tie_s (ID_CONTACT int NOT NULL);
CREATE TABLE #t2_log (K int IDENTITY(1,1) PRIMARY KEY, BLOCK nvarchar(40) NOT NULL, AT datetime2(3) NOT NULL);

-- отметка о запуске (после подготовки временных: их ошибка не должна заблокировать повтор): при обрыве (тайм-аут,
-- перезапуск) тяжёлая сверка повторно не пойдёт
INSERT INTO dbo.I_DISCOUNT_PROC_BACKUP (PROC_NAME, SAVED_AT, DEFINITION)
VALUES (@rep_name, @run_at, CONCAT(N'{"status":"started","act_date":"', @act_date, N'"}'));

BEGIN TRY
    SET @step = N'run';
    EXEC sys.sp_executesql @body;

    -- ============================== 3. СВЕРКА #new С I_CVM_CONTACT ==============================
    SET @step = N'compare';
    SELECT @minutes = DATEDIFF(second, MIN(AT), MAX(AT)) / 60 FROM #t2_log;
    SELECT @dup_old = COUNT_BIG(*) FROM (SELECT x = 1 FROM dbo.I_CVM_CONTACT (nolock)
                                         GROUP BY ID_COMPANY, ID_ORGANIZATION, ID_CONTACT HAVING COUNT(*) > 1) q;
    SELECT @dup_new = COUNT_BIG(*) FROM (SELECT x = 1 FROM #new
                                         GROUP BY ID_COMPANY, ID_ORGANIZATION, ID_CONTACT HAVING COUNT(*) > 1) q;
    -- условие CC-1 (П7 аудита): I_CONTACT — одна строка на клиента
    SELECT @dup_icontact = COUNT_BIG(*) FROM (SELECT x = 1 FROM dbo.I_CONTACT (nolock)
                                              GROUP BY ID_COMPANY, ID_CONTACT HAVING COUNT(*) > 1) q;

    SELECT
      N_OLD = SUM(o.P_), N_NEW = SUM(n.P_)
    , ONLY_OLD = SUM(CASE WHEN n.P_ IS NULL THEN 1 ELSE 0 END), ONLY_NEW = SUM(CASE WHEN o.P_ IS NULL THEN 1 ELSE 0 END)
    , D_SEGMENT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[SEGMENT] = n.[SEGMENT] OR (o.[SEGMENT] IS NULL AND n.[SEGMENT] IS NULL) THEN 0 ELSE 1 END)
    , DX_SEGMENT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL OR tw.ID_CONTACT IS NOT NULL THEN 0 WHEN o.[SEGMENT] = n.[SEGMENT] OR (o.[SEGMENT] IS NULL AND n.[SEGMENT] IS NULL) THEN 0 ELSE 1 END)
    , D_TOKENS = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[TOKENS] = n.[TOKENS] OR (o.[TOKENS] IS NULL AND n.[TOKENS] IS NULL) THEN 0 ELSE 1 END)
    , D_HAS_PUSH = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[HAS_PUSH] = n.[HAS_PUSH] OR (o.[HAS_PUSH] IS NULL AND n.[HAS_PUSH] IS NULL) THEN 0 ELSE 1 END)
    , D_HAS_EMAIL = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[HAS_EMAIL] = n.[HAS_EMAIL] OR (o.[HAS_EMAIL] IS NULL AND n.[HAS_EMAIL] IS NULL) THEN 0 ELSE 1 END)
    , D_REFERENCE_DATE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[REFERENCE_DATE] = n.[REFERENCE_DATE] OR (o.[REFERENCE_DATE] IS NULL AND n.[REFERENCE_DATE] IS NULL) THEN 0 ELSE 1 END)
    , D_ID_SALE_CHANNEL = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[ID_SALE_CHANNEL] = n.[ID_SALE_CHANNEL] OR (o.[ID_SALE_CHANNEL] IS NULL AND n.[ID_SALE_CHANNEL] IS NULL) THEN 0 ELSE 1 END)
    , D_SALE_CHANNEL = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[SALE_CHANNEL] = n.[SALE_CHANNEL] OR (o.[SALE_CHANNEL] IS NULL AND n.[SALE_CHANNEL] IS NULL) THEN 0 ELSE 1 END)
    , D_PRICE_INDEX = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[PRICE_INDEX] = n.[PRICE_INDEX] OR (o.[PRICE_INDEX] IS NULL AND n.[PRICE_INDEX] IS NULL) THEN 0 ELSE 1 END)
    , D_ID_PRICE_SEGMENT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[ID_PRICE_SEGMENT] = n.[ID_PRICE_SEGMENT] OR (o.[ID_PRICE_SEGMENT] IS NULL AND n.[ID_PRICE_SEGMENT] IS NULL) THEN 0 ELSE 1 END)
    , D_PRICE_SEGMENT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[PRICE_SEGMENT] = n.[PRICE_SEGMENT] OR (o.[PRICE_SEGMENT] IS NULL AND n.[PRICE_SEGMENT] IS NULL) THEN 0 ELSE 1 END)
    , D_LOYALTY_INDEX = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[LOYALTY_INDEX] = n.[LOYALTY_INDEX] OR (o.[LOYALTY_INDEX] IS NULL AND n.[LOYALTY_INDEX] IS NULL) THEN 0 ELSE 1 END)
    , D_ID_LOYALTY_SEGMENT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[ID_LOYALTY_SEGMENT] = n.[ID_LOYALTY_SEGMENT] OR (o.[ID_LOYALTY_SEGMENT] IS NULL AND n.[ID_LOYALTY_SEGMENT] IS NULL) THEN 0 ELSE 1 END)
    , D_LOYALTY_SEGMENT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[LOYALTY_SEGMENT] = n.[LOYALTY_SEGMENT] OR (o.[LOYALTY_SEGMENT] IS NULL AND n.[LOYALTY_SEGMENT] IS NULL) THEN 0 ELSE 1 END)
    , D_FIRST_DATA = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[FIRST_DATA] = n.[FIRST_DATA] OR (o.[FIRST_DATA] IS NULL AND n.[FIRST_DATA] IS NULL) THEN 0 ELSE 1 END)
    , D_LAST_DATA = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[LAST_DATA] = n.[LAST_DATA] OR (o.[LAST_DATA] IS NULL AND n.[LAST_DATA] IS NULL) THEN 0 ELSE 1 END)
    , D_LAST_YM = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[LAST_YM] = n.[LAST_YM] OR (o.[LAST_YM] IS NULL AND n.[LAST_YM] IS NULL) THEN 0 ELSE 1 END)
    , D_FIRST_YM = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[FIRST_YM] = n.[FIRST_YM] OR (o.[FIRST_YM] IS NULL AND n.[FIRST_YM] IS NULL) THEN 0 ELSE 1 END)
    , D_VISITS = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[VISITS] = n.[VISITS] OR (o.[VISITS] IS NULL AND n.[VISITS] IS NULL) THEN 0 ELSE 1 END)
    , D_FREQ_SCORE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[FREQ_SCORE] = n.[FREQ_SCORE] OR (o.[FREQ_SCORE] IS NULL AND n.[FREQ_SCORE] IS NULL) THEN 0 ELSE 1 END)
    , D_CHECKS = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[CHECKS] = n.[CHECKS] OR (o.[CHECKS] IS NULL AND n.[CHECKS] IS NULL) THEN 0 ELSE 1 END)
    , D_VISITS_PER_WEEK = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[VISITS_PER_WEEK] = n.[VISITS_PER_WEEK] OR (o.[VISITS_PER_WEEK] IS NULL AND n.[VISITS_PER_WEEK] IS NULL) THEN 0 ELSE 1 END)
    , D_AVG_VISIT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[AVG_VISIT] = n.[AVG_VISIT] OR (o.[AVG_VISIT] IS NULL AND n.[AVG_VISIT] IS NULL) THEN 0 ELSE 1 END)
    , D_CHECK_SCORE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[CHECK_SCORE] = n.[CHECK_SCORE] OR (o.[CHECK_SCORE] IS NULL AND n.[CHECK_SCORE] IS NULL) THEN 0 ELSE 1 END)
    , D_AVG_CHECK = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[AVG_CHECK] = n.[AVG_CHECK] OR (o.[AVG_CHECK] IS NULL AND n.[AVG_CHECK] IS NULL) THEN 0 ELSE 1 END)
    , D_BUDGET = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[BUDGET] = n.[BUDGET] OR (o.[BUDGET] IS NULL AND n.[BUDGET] IS NULL) THEN 0 ELSE 1 END)
    , D_BUDGET_SCORE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[BUDGET_SCORE] = n.[BUDGET_SCORE] OR (o.[BUDGET_SCORE] IS NULL AND n.[BUDGET_SCORE] IS NULL) THEN 0 ELSE 1 END)
    , D_AVG_COST_SKU = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[AVG_COST_SKU] = n.[AVG_COST_SKU] OR (o.[AVG_COST_SKU] IS NULL AND n.[AVG_COST_SKU] IS NULL) THEN 0 ELSE 1 END)
    , D_AVG_SKU = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[AVG_SKU] = n.[AVG_SKU] OR (o.[AVG_SKU] IS NULL AND n.[AVG_SKU] IS NULL) THEN 0 ELSE 1 END)
    , D_SHARE_WEEKEND = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[SHARE_WEEKEND] = n.[SHARE_WEEKEND] OR (o.[SHARE_WEEKEND] IS NULL AND n.[SHARE_WEEKEND] IS NULL) THEN 0 ELSE 1 END)
    , D_SHARE_WORKDAY = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[SHARE_WORKDAY] = n.[SHARE_WORKDAY] OR (o.[SHARE_WORKDAY] IS NULL AND n.[SHARE_WORKDAY] IS NULL) THEN 0 ELSE 1 END)
    , D_TIME_PURCHASE_WEEKEND = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[TIME_PURCHASE_WEEKEND] = n.[TIME_PURCHASE_WEEKEND] OR (o.[TIME_PURCHASE_WEEKEND] IS NULL AND n.[TIME_PURCHASE_WEEKEND] IS NULL) THEN 0 ELSE 1 END)
    , D_TIME_PURCHASE_WORKDAY = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[TIME_PURCHASE_WORKDAY] = n.[TIME_PURCHASE_WORKDAY] OR (o.[TIME_PURCHASE_WORKDAY] IS NULL AND n.[TIME_PURCHASE_WORKDAY] IS NULL) THEN 0 ELSE 1 END)
    , D_REAL_SALE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[REAL_SALE] = n.[REAL_SALE] OR (o.[REAL_SALE] IS NULL AND n.[REAL_SALE] IS NULL) THEN 0 ELSE 1 END)
    , D_CARD_SALE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[CARD_SALE] = n.[CARD_SALE] OR (o.[CARD_SALE] IS NULL AND n.[CARD_SALE] IS NULL) THEN 0 ELSE 1 END)
    , D_MAX_CHECK = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[MAX_CHECK] = n.[MAX_CHECK] OR (o.[MAX_CHECK] IS NULL AND n.[MAX_CHECK] IS NULL) THEN 0 ELSE 1 END)
    , D_POTENCIAL = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[POTENCIAL] = n.[POTENCIAL] OR (o.[POTENCIAL] IS NULL AND n.[POTENCIAL] IS NULL) THEN 0 ELSE 1 END)
    , D_MAIN_TARGET = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[MAIN_TARGET] = n.[MAIN_TARGET] OR (o.[MAIN_TARGET] IS NULL AND n.[MAIN_TARGET] IS NULL) THEN 0 ELSE 1 END)
    , D_CHURN_RATE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[CHURN_RATE] = n.[CHURN_RATE] OR (o.[CHURN_RATE] IS NULL AND n.[CHURN_RATE] IS NULL) THEN 0 ELSE 1 END)
    , D_PUSH_DELIV_RATE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[PUSH_DELIV_RATE] = n.[PUSH_DELIV_RATE] OR (o.[PUSH_DELIV_RATE] IS NULL AND n.[PUSH_DELIV_RATE] IS NULL) THEN 0 ELSE 1 END)
    , D_PUSH_CLICK_RATE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[PUSH_CLICK_RATE] = n.[PUSH_CLICK_RATE] OR (o.[PUSH_CLICK_RATE] IS NULL AND n.[PUSH_CLICK_RATE] IS NULL) THEN 0 ELSE 1 END)
    , D_ID_RFM_CLUSTER = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[ID_RFM_CLUSTER] = n.[ID_RFM_CLUSTER] OR (o.[ID_RFM_CLUSTER] IS NULL AND n.[ID_RFM_CLUSTER] IS NULL) THEN 0 ELSE 1 END)
    , D_RFM_CLUSTER = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[RFM_CLUSTER] = n.[RFM_CLUSTER] OR (o.[RFM_CLUSTER] IS NULL AND n.[RFM_CLUSTER] IS NULL) THEN 0 ELSE 1 END)
    , D_ID_CLUSTER = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[ID_CLUSTER] = n.[ID_CLUSTER] OR (o.[ID_CLUSTER] IS NULL AND n.[ID_CLUSTER] IS NULL) THEN 0 ELSE 1 END)
    , D_CLUSTER = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[CLUSTER] = n.[CLUSTER] OR (o.[CLUSTER] IS NULL AND n.[CLUSTER] IS NULL) THEN 0 ELSE 1 END)
    , D_CONTROL_GROUP = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[CONTROL_GROUP] = n.[CONTROL_GROUP] OR (o.[CONTROL_GROUP] IS NULL AND n.[CONTROL_GROUP] IS NULL) THEN 0 ELSE 1 END)
    , D_LTV = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[LTV] = n.[LTV] OR (o.[LTV] IS NULL AND n.[LTV] IS NULL) THEN 0 ELSE 1 END)
    , D_LOVE_STORE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[LOVE_STORE] = n.[LOVE_STORE] OR (o.[LOVE_STORE] IS NULL AND n.[LOVE_STORE] IS NULL) THEN 0 ELSE 1 END)
    , DX_LOVE_STORE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL OR ts.ID_CONTACT IS NOT NULL THEN 0 WHEN o.[LOVE_STORE] = n.[LOVE_STORE] OR (o.[LOVE_STORE] IS NULL AND n.[LOVE_STORE] IS NULL) THEN 0 ELSE 1 END)
    , D_ID_DARKSTORE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[ID_DARKSTORE] = n.[ID_DARKSTORE] OR (o.[ID_DARKSTORE] IS NULL AND n.[ID_DARKSTORE] IS NULL) THEN 0 ELSE 1 END)
    , DX_ID_DARKSTORE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL OR ts.ID_CONTACT IS NOT NULL THEN 0 WHEN o.[ID_DARKSTORE] = n.[ID_DARKSTORE] OR (o.[ID_DARKSTORE] IS NULL AND n.[ID_DARKSTORE] IS NULL) THEN 0 ELSE 1 END)
    , D_AFFINITIVE_SCORE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[AFFINITIVE_SCORE] = n.[AFFINITIVE_SCORE] OR (o.[AFFINITIVE_SCORE] IS NULL AND n.[AFFINITIVE_SCORE] IS NULL) THEN 0 ELSE 1 END)
    , D_FAV_PRODUCT_CHOICE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[FAV_PRODUCT_CHOICE] = n.[FAV_PRODUCT_CHOICE] OR (o.[FAV_PRODUCT_CHOICE] IS NULL AND n.[FAV_PRODUCT_CHOICE] IS NULL) THEN 0 ELSE 1 END)
    , D_FAV_CATEGORY_CHOICE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[FAV_CATEGORY_CHOICE] = n.[FAV_CATEGORY_CHOICE] OR (o.[FAV_CATEGORY_CHOICE] IS NULL AND n.[FAV_CATEGORY_CHOICE] IS NULL) THEN 0 ELSE 1 END)
    , D_FAV_PRODUCT_USE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[FAV_PRODUCT_USE] = n.[FAV_PRODUCT_USE] OR (o.[FAV_PRODUCT_USE] IS NULL AND n.[FAV_PRODUCT_USE] IS NULL) THEN 0 ELSE 1 END)
    , D_FAV_CATEGORY_USE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[FAV_CATEGORY_USE] = n.[FAV_CATEGORY_USE] OR (o.[FAV_CATEGORY_USE] IS NULL AND n.[FAV_CATEGORY_USE] IS NULL) THEN 0 ELSE 1 END)
    , D_PP_USE = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[PP_USE] = n.[PP_USE] OR (o.[PP_USE] IS NULL AND n.[PP_USE] IS NULL) THEN 0 ELSE 1 END)
    , D_CVM_PARTICIPANT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[CVM_PARTICIPANT] = n.[CVM_PARTICIPANT] OR (o.[CVM_PARTICIPANT] IS NULL AND n.[CVM_PARTICIPANT] IS NULL) THEN 0 ELSE 1 END)
    , D_LOYALTY_PROMO_PARTICIPANT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[LOYALTY_PROMO_PARTICIPANT] = n.[LOYALTY_PROMO_PARTICIPANT] OR (o.[LOYALTY_PROMO_PARTICIPANT] IS NULL AND n.[LOYALTY_PROMO_PARTICIPANT] IS NULL) THEN 0 ELSE 1 END)
    , D_PUSH_CLICK_COUNT = SUM(CASE WHEN o.P_ IS NULL OR n.P_ IS NULL THEN 0 WHEN o.[PUSH_CLICK_COUNT] = n.[PUSH_CLICK_COUNT] OR (o.[PUSH_CLICK_COUNT] IS NULL AND n.[PUSH_CLICK_COUNT] IS NULL) THEN 0 ELSE 1 END)
    INTO #cmp
    FROM (SELECT *, P_ = 1 FROM dbo.I_CVM_CONTACT (nolock)) AS o
         FULL JOIN (SELECT *, P_ = 1 FROM #new) AS n
         ON n.ID_COMPANY = o.ID_COMPANY AND n.ID_ORGANIZATION = o.ID_ORGANIZATION AND n.ID_CONTACT = o.ID_CONTACT
         LEFT JOIN #tie_w AS tw ON tw.ID_CONTACT = ISNULL(o.ID_CONTACT, n.ID_CONTACT)
         LEFT JOIN #tie_s AS ts ON ts.ID_CONTACT = ISNULL(o.ID_CONTACT, n.ID_CONTACT);

    -- условие применения: строки и ключи те же; строгие колонки совпали везде; SEGMENT, LOVE_STORE, ID_DARKSTORE — у всех,
    -- кроме «ничьих»
    SELECT @why += CONCAT(
          IIF(N_OLD <> N_NEW OR ONLY_OLD <> 0 OR ONLY_NEW <> 0, N'rows/keys differ; ', N'')
        , IIF(D_TOKENS + D_HAS_PUSH + D_HAS_EMAIL + D_REFERENCE_DATE + D_ID_SALE_CHANNEL + D_SALE_CHANNEL + D_ID_PRICE_SEGMENT + D_PRICE_SEGMENT + D_ID_LOYALTY_SEGMENT + D_LOYALTY_SEGMENT + D_FIRST_DATA + D_LAST_DATA + D_LAST_YM + D_FIRST_YM + D_VISITS + D_FREQ_SCORE + D_CHECKS + D_VISITS_PER_WEEK + D_AVG_VISIT + D_CHECK_SCORE + D_AVG_CHECK + D_BUDGET + D_BUDGET_SCORE + D_AVG_COST_SKU + D_AVG_SKU + D_SHARE_WEEKEND + D_SHARE_WORKDAY + D_TIME_PURCHASE_WEEKEND + D_TIME_PURCHASE_WORKDAY + D_REAL_SALE + D_CARD_SALE + D_MAX_CHECK + D_POTENCIAL + D_MAIN_TARGET + D_CHURN_RATE + D_PUSH_DELIV_RATE + D_PUSH_CLICK_RATE + D_ID_RFM_CLUSTER + D_RFM_CLUSTER + D_ID_CLUSTER + D_CLUSTER + D_CONTROL_GROUP + D_LTV + D_FAV_PRODUCT_CHOICE + D_FAV_CATEGORY_CHOICE + D_FAV_PRODUCT_USE + D_FAV_CATEGORY_USE + D_PUSH_CLICK_COUNT <> 0
            , N'strict columns differ: ' + CONCAT_WS(N',', IIF(D_TOKENS <> 0, N'TOKENS', NULL), IIF(D_HAS_PUSH <> 0, N'HAS_PUSH', NULL), IIF(D_HAS_EMAIL <> 0, N'HAS_EMAIL', NULL), IIF(D_REFERENCE_DATE <> 0, N'REFERENCE_DATE', NULL), IIF(D_ID_SALE_CHANNEL <> 0, N'ID_SALE_CHANNEL', NULL), IIF(D_SALE_CHANNEL <> 0, N'SALE_CHANNEL', NULL), IIF(D_ID_PRICE_SEGMENT <> 0, N'ID_PRICE_SEGMENT', NULL), IIF(D_PRICE_SEGMENT <> 0, N'PRICE_SEGMENT', NULL), IIF(D_ID_LOYALTY_SEGMENT <> 0, N'ID_LOYALTY_SEGMENT', NULL), IIF(D_LOYALTY_SEGMENT <> 0, N'LOYALTY_SEGMENT', NULL), IIF(D_FIRST_DATA <> 0, N'FIRST_DATA', NULL), IIF(D_LAST_DATA <> 0, N'LAST_DATA', NULL), IIF(D_LAST_YM <> 0, N'LAST_YM', NULL), IIF(D_FIRST_YM <> 0, N'FIRST_YM', NULL), IIF(D_VISITS <> 0, N'VISITS', NULL), IIF(D_FREQ_SCORE <> 0, N'FREQ_SCORE', NULL), IIF(D_CHECKS <> 0, N'CHECKS', NULL), IIF(D_VISITS_PER_WEEK <> 0, N'VISITS_PER_WEEK', NULL), IIF(D_AVG_VISIT <> 0, N'AVG_VISIT', NULL), IIF(D_CHECK_SCORE <> 0, N'CHECK_SCORE', NULL), IIF(D_AVG_CHECK <> 0, N'AVG_CHECK', NULL), IIF(D_BUDGET <> 0, N'BUDGET', NULL), IIF(D_BUDGET_SCORE <> 0, N'BUDGET_SCORE', NULL), IIF(D_AVG_COST_SKU <> 0, N'AVG_COST_SKU', NULL), IIF(D_AVG_SKU <> 0, N'AVG_SKU', NULL), IIF(D_SHARE_WEEKEND <> 0, N'SHARE_WEEKEND', NULL), IIF(D_SHARE_WORKDAY <> 0, N'SHARE_WORKDAY', NULL), IIF(D_TIME_PURCHASE_WEEKEND <> 0, N'TIME_PURCHASE_WEEKEND', NULL), IIF(D_TIME_PURCHASE_WORKDAY <> 0, N'TIME_PURCHASE_WORKDAY', NULL), IIF(D_REAL_SALE <> 0, N'REAL_SALE', NULL), IIF(D_CARD_SALE <> 0, N'CARD_SALE', NULL), IIF(D_MAX_CHECK <> 0, N'MAX_CHECK', NULL), IIF(D_POTENCIAL <> 0, N'POTENCIAL', NULL), IIF(D_MAIN_TARGET <> 0, N'MAIN_TARGET', NULL), IIF(D_CHURN_RATE <> 0, N'CHURN_RATE', NULL), IIF(D_PUSH_DELIV_RATE <> 0, N'PUSH_DELIV_RATE', NULL), IIF(D_PUSH_CLICK_RATE <> 0, N'PUSH_CLICK_RATE', NULL), IIF(D_ID_RFM_CLUSTER <> 0, N'ID_RFM_CLUSTER', NULL), IIF(D_RFM_CLUSTER <> 0, N'RFM_CLUSTER', NULL), IIF(D_ID_CLUSTER <> 0, N'ID_CLUSTER', NULL), IIF(D_CLUSTER <> 0, N'CLUSTER', NULL), IIF(D_CONTROL_GROUP <> 0, N'CONTROL_GROUP', NULL), IIF(D_LTV <> 0, N'LTV', NULL), IIF(D_FAV_PRODUCT_CHOICE <> 0, N'FAV_PRODUCT_CHOICE', NULL), IIF(D_FAV_CATEGORY_CHOICE <> 0, N'FAV_CATEGORY_CHOICE', NULL), IIF(D_FAV_PRODUCT_USE <> 0, N'FAV_PRODUCT_USE', NULL), IIF(D_FAV_CATEGORY_USE <> 0, N'FAV_CATEGORY_USE', NULL), IIF(D_PUSH_CLICK_COUNT <> 0, N'PUSH_CLICK_COUNT', NULL)) + N'; ', N'')
        , IIF(DX_SEGMENT <> 0, N'SEGMENT differs outside ties; ', N'')
        , IIF(DX_LOVE_STORE + DX_ID_DARKSTORE <> 0, N'LOVE_STORE differs outside ties; ', N''))
    FROM #cmp;

    SELECT @seg_json = (SELECT SEGMENT, N_OLD = SUM(O_), N_NEW = SUM(N_)
                        FROM (SELECT SEGMENT, O_ = 1, N_ = 0 FROM dbo.I_CVM_CONTACT (nolock)
                              UNION ALL
                              SELECT SEGMENT, 0, 1 FROM #new) q
                        GROUP BY SEGMENT ORDER BY SEGMENT FOR JSON PATH);
    SELECT @log_json = (SELECT BLOCK, AT = CONVERT(char(8), AT, 108) FROM #t2_log ORDER BY K FOR JSON PATH);
    SELECT @cmp_json = (SELECT * FROM #cmp FOR JSON PATH, WITHOUT_ARRAY_WRAPPER, INCLUDE_NULL_VALUES);

    IF @dup_old <> 0 OR @dup_new <> 0 SET @why += N'key duplicates; ';
    IF @minutes IS NULL OR @minutes > @max_min SET @why += CONCAT(N'run took ', @minutes, N' min > ', @max_min, N'; ');
    SET @why = ISNULL(@why, N'');

    SET @report = (SELECT status = IIF(@why = N'', N'gate passed', N'not applied'), why = @why, act_date = @act_date
                        , minutes = @minutes, max_min = @max_min, dup_old = @dup_old, dup_new = @dup_new
                        , dup_i_contact = @dup_icontact
                        , tie_w = (SELECT COUNT(*) FROM #tie_w), tie_s = (SELECT COUNT(*) FROM #tie_s)
                        , cmp = JSON_QUERY(@cmp_json), segments = JSON_QUERY(@seg_json), blocks = JSON_QUERY(@log_json)
                   FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
    UPDATE dbo.I_DISCOUNT_PROC_BACKUP SET DEFINITION = @report WHERE PROC_NAME = @rep_name AND SAVED_AT = @run_at;

    -- ============================== 4. ПРИМЕНЕНИЕ — ТОЛЬКО ЕСЛИ ВСЁ СОВПАЛО ==============================
    IF @why = N''
    BEGIN
        SET @step = N'alter';
        SET @pos = CHARINDEX(@hdr_c COLLATE Latin1_General_BIN2, @new_def COLLATE Latin1_General_BIN2);
        SET @alter = STUFF(@new_def, @pos, LEN(N'CREATE'), N'ALTER');
        BEGIN TRAN;
            INSERT INTO dbo.I_DISCOUNT_PROC_BACKUP (PROC_NAME, SAVED_AT, DEFINITION)
            VALUES (N'CVM_CONTACT', SYSDATETIME(), @def);
            EXEC sys.sp_executesql @alter;
            IF HASHBYTES('SHA2_256', REPLACE(OBJECT_DEFINITION(OBJECT_ID(N'dbo.CVM_CONTACT')) COLLATE Latin1_General_BIN2,
                                             @hdr_a, @hdr_c)) <> @sha_new
                THROW 50020, N'T2: text after ALTER does not match — rolled back.', 1;
        COMMIT;
        UPDATE dbo.I_DISCOUNT_PROC_BACKUP SET DEFINITION = JSON_MODIFY(DEFINITION, '$.status', N'applied')
        WHERE PROC_NAME = @rep_name AND SAVED_AT = @run_at;
        SET @msg = CONCAT(N'T2 APPLIED: CVM_CONTACT altered; run ', @minutes, N' min; all compared columns match.');
        PRINT @msg;
    END
    ELSE
    BEGIN
        SET @msg = LEFT(CONCAT(N'T2 NOT APPLIED (procedure unchanged): ', @why,
                               N' — see I_DISCOUNT_PROC_BACKUP PROC_NAME = ''CVM_CONTACT T2 ...'''), 2040);
        RAISERROR(N'%s', 16, 1, @msg);   -- видно в CVM_API_JOB_LOG; при повторе через 10 минут скрипт увидит строку сверки и выйдет
    END
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    SET @msg = LEFT(CONCAT(N'T2 ERROR at ', @step, N' (procedure unchanged): ', ERROR_NUMBER(), N' line ', ERROR_LINE(),
                           N': ', ERROR_MESSAGE()), 2040);
    SELECT @log_json = (SELECT BLOCK, AT = CONVERT(char(8), AT, 108) FROM #t2_log ORDER BY K FOR JSON PATH);
    UPDATE dbo.I_DISCOUNT_PROC_BACKUP
    SET DEFINITION = (SELECT status = N'error', step = @step, error = ERROR_MESSAGE(), error_number = ERROR_NUMBER()
                           , error_line = ERROR_LINE(), act_date = @act_date, blocks = JSON_QUERY(@log_json)
                           , report = JSON_QUERY(@report)   -- сверка, если ошибка случилась на ALTER
                      FOR JSON PATH, WITHOUT_ARRAY_WRAPPER)
    WHERE PROC_NAME = @rep_name AND SAVED_AT = @run_at;
    RAISERROR(N'%s', 16, 1, @msg);
END CATCH
GO
